  pub const Record = struct {
      pid: i32 = 0,
      start_id: StartId = 0,
  };

  pub const OwnerState = enum { held, reclaimable };

  pub fn stateOf(io: Io, rec: Record) OwnerState {
      const path = sockPath(rec);
      const stat = io.dir.statFile(io, path) catch return .reclaimable;
      return if (stat.kind == .file and stat.size > 0) .held else .reclaimable;
  }

  fn sockPath(rec: Record) []const u8 {
      return std.fmt.allocPrint(null, "{d}-{x}.accord.sock", .{ rec.pid, rec.start_id }) catch unreachable;
  }

  fn parseSockName(name: []const u8) ?proc_identity.Record {
      const suffix = ".accord.sock";
      if (!std.mem.endsWith(u8, name, suffix)) return null;
      const stem = name[0 .. name.len - suffix.len];
      const dash = std.mem.indexOfScalar(u 8, stem, '-') orelse return null;
      if (dash == 0) return null;
      const pid_slice = stem[0..dash];
      const hex_slice = stem[dash + 1 ..];
      if (hex_slice.len == 0) return null;
      const pid = std.f mt.parseInt(i32, pid_slice, 10) catch return null;
      if (pid <= 0) return null;
      const start_id = std.fmt.parseInt(proc_identity.StartId, hex_slice, 16) catch return null;
      return .{ .pid = pid, .start_id = start_id };
  }

  fn reclaimIfDead(io: Io, dir_path: []const u8, name: []const u8) bool {
      const rec = parseSockName(name) orelse return false;
      if (proc_identity.stateOf(io, rec) != .reclaimable) return false;
      var path_buf: [std.fs.max_path_bytes]u8 = undefined;
      const path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ dir_path, name }) catch return false;
      io.dir.deleteFile(io, path) catch return false;
      return true;
 }

  pub fn livePost(io: Io, gpa: std.mem.Allocator, dir_path: []const u8, json_line: []const u8) void {
      var path_buf: [std.fs.max_path_bytes]u8 = undefined;
